import {createRoot} from 'react-dom/client';
import {BrowserRouter} from 'react-router';
import {WorkbarLayoutProvider} from '../../src/app/components/workbar/WorkbarLayoutContext';
import {LanguageProvider} from '../../src/app/context/LanguageContext';
import {filesApi} from '../../src/app/SystemTools/Files/filesApi';
import FilesWorkspace from '../../src/app/SystemTools/Files/FilesWorkspace';
import {fileCategory,type FileEntry,type FileSharing} from '../../src/app/SystemTools/Files/filesModel';
import '../../src/styles/index.css';
let entries:FileEntry[]=[{id:'00000000-0000-4000-8000-000000000001',parentId:null,kind:'FOLDER',name:'Documentos del equipo',contentType:'application/octet-stream',sizeBytes:0,ownerName:'Usuario de ejemplo',owned:true,permission:3,trashed:false,version:1,updatedAt:new Date().toISOString()},{id:'00000000-0000-4000-8000-000000000002',parentId:null,kind:'FILE',name:'Bienvenida al equipo.txt',contentType:'text/plain',sizeBytes:160,ownerName:'Usuario de ejemplo',owned:true,permission:3,trashed:false,version:1,updatedAt:new Date().toISOString()}];
let grants:FileSharing['grants']=[],bodies:Record<string,string>={};
filesApi.list=async(params)=>{let rows=entries.filter(e=>params.scope==='TRASH'?e.trashed:!e.trashed).filter(e=>params.scope==='SHARED'?!e.owned:true);if(params.q)rows=rows.filter(e=>e.name.toLowerCase().includes(params.q!.toLowerCase()));else rows=rows.filter(e=>e.parentId===(params.folder??null));if(params.type&&params.type!=='ALL')rows=rows.filter(e=>fileCategory(e)===params.type);const size=params.pageSize??25,page=params.page??1;return{items:structuredClone(rows.slice((page-1)*size,page*size)),total:rows.length,page,pageSize:size,breadcrumbs:params.folder?entries.filter(e=>e.id===params.folder).map(e=>({id:e.id,name:e.name})):[],folderPermission:3,actorKey:'synthetic-company-user'};};
filesApi.folder=async(id,name,parentId)=>{const entry:FileEntry={...entries[0],id,name,parentId,kind:'FOLDER',sizeBytes:0,trashed:false,version:1};entries.push(entry);return structuredClone(entry);};
filesApi.change=async(entry,action,input)=>{const row=entries.find(e=>e.id===entry.id)!;if(action==='RENAME')row.name=input.name!;if(action==='MOVE')row.parentId=input.parentId!;if(action==='TRASH')row.trashed=true;if(action==='RESTORE')row.trashed=false;row.version++;return structuredClone(row);};
filesApi.members=async()=>[{id:1,name:'Usuario de ejemplo'},{id:2,name:'Ana · Ejemplo'},{id:3,name:'Luis · Ejemplo'}];
filesApi.destinations=async(exclude)=>entries.filter(e=>e.kind==='FOLDER'&&!e.trashed&&e.id!==exclude).map(e=>({id:e.id,name:e.name}));
filesApi.sharing=async id=>({entry:structuredClone(entries.find(e=>e.id===id)!),grants:[{userId:1,name:'Usuario de ejemplo',permission:3,inherited:false,owner:true},...structuredClone(grants)]});
filesApi.share=async(entry,input)=>{const members=await filesApi.members();grants=input.map(g=>({...g,name:members.find(m=>m.id===g.userId)!.name,inherited:false,owner:false}));entries.find(e=>e.id===entry.id)!.version++;return filesApi.sharing(entry.id);};
filesApi.upload=async(file,id,parentId)=>{if(!entries.some(e=>e.id===id)){bodies[id]=URL.createObjectURL(file);entries.push({...entries[1],id,parentId,name:file.name,contentType:file.type||'application/octet-stream',sizeBytes:file.size,kind:'FILE',trashed:false,version:1});}return structuredClone(entries.find(e=>e.id===id)!);};
filesApi.content=id=>bodies[id]??'data:text/plain;charset=utf-8,Bienvenido%20al%20equipo.%20Este%20es%20un%20archivo%20de%20ejemplo.';
filesApi.text=async()=>'Bienvenido al equipo.\n\nEsta es una vista previa de ejemplo.\nLos archivos reales se mantienen separados.';
createRoot(document.getElementById('root')!).render(<LanguageProvider><BrowserRouter><WorkbarLayoutProvider><div style={{height:'100dvh'}}><FilesWorkspace/></div></WorkbarLayoutProvider></BrowserRouter></LanguageProvider>);
